get_tax_settings.code:
final response = await client.taxSettings.getTaxSettings();
final taxSettings = (response.map as Map)['tax_settings'] as Map;
print(taxSettings['tax_rate_for_customers']);
print(taxSettings['prices_in_catalog']);
print(taxSettings['tax_message']);

put_tax_settings.code:
final response = await client.taxSettings.putTaxSettings({
  'tax_settings': {'tax_message': 'All prices include GST'},
});
final taxSettings = (response.map as Map)['tax_settings'] as Map;
print(taxSettings['tax_message']);

patch_tax_settings.code:
final response = await client.taxSettings.patchTaxSettings({
  'tax_settings': {'is_price_shown_with_tax': true},
});
final taxSettings = (response.map as Map)['tax_settings'] as Map;
print(taxSettings['is_price_shown_with_tax']);
